  'forces-y5': {
    title: 'Forces: Gravity, Resistance and Mechanisms',
    year: 5,
    strand: 'Forces',
    questions: [
      { id: 'fry5-1', question: 'What is gravity?', options: ['A force that pulls objects towards each other, like Earth pulling objects down', 'A force that pushes objects apart', 'A type of light', 'A type of sound'], correct: 'A force that pulls objects towards each other, like Earth pulling objects down', hint: 'It is why things fall to the ground' },
      { id: 'fry5-2', question: 'What is air resistance?', options: ['A force that slows down objects moving through air', 'A force that speeds up objects in air', 'A type of magnetism', 'A type of gravity only found in space'], correct: 'A force that slows down objects moving through air', hint: 'Think about a parachute slowing a fall' },
      { id: 'fry5-3', question: 'What is water resistance?', options: ['A force that slows down objects moving through water', 'A force found only on land', 'A type of gravity', 'A force that speeds objects up in water'], correct: 'A force that slows down objects moving through water', hint: 'Think about how hard it is to run through a swimming pool' },
      { id: 'fry5-4', question: 'What is a lever?', options: ['A simple machine that helps lift or move loads with less effort', 'A type of magnet', 'A type of liquid', 'A type of gas'], correct: 'A simple machine that helps lift or move loads with less effort', hint: 'Think of a see-saw' },
      { id: 'fry5-5', question: 'What is a pulley used for?', options: ['To help lift heavy objects using a wheel and rope/chain', 'To measure temperature', 'To generate electricity only', 'To measure sound'], correct: 'To help lift heavy objects using a wheel and rope/chain', hint: 'Think of a flagpole or a crane' },
      { id: 'fry5-6', question: 'What are gears used for?', options: ['To transfer force and change speed or direction of movement', 'To measure light', 'To create sound', 'To absorb water'], correct: 'To transfer force and change speed or direction of movement', hint: 'Think of a bicycle\u2019s gear system' },
      { id: 'fry5-7', question: 'Why does a heavier object not necessarily fall faster than a lighter one (ignoring air resistance)?', options: ['Gravity accelerates all objects at the same rate', 'Heavier objects always fall faster', 'Lighter objects always fall faster', 'Weight has no connection to falling at all'], correct: 'Gravity accelerates all objects at the same rate', hint: 'This was famously demonstrated by Galileo' },
      { id: 'fry5-8', question: 'Why might a cyclist wear smooth, tight-fitting clothing when racing?', options: ['To reduce air resistance and go faster', 'To increase air resistance', 'To increase friction with the road', 'It has no effect on speed'], correct: 'To reduce air resistance and go faster', hint: 'Less drag can help you move more efficiently' },
      { id: 'fry5-9', question: 'What simple machine helps you cut with scissors?', options: ['A lever', 'A pulley', 'A gear', 'A wheel'], correct: 'A lever', hint: 'Scissors use two levers joined together' },
      { id: 'fry5-10', question: 'How does the shape of a parachute increase air resistance?', options: ['Its large surface area catches more air', 'It has no effect on air resistance', 'It reduces air resistance completely', 'It only works underwater'], correct: 'Its large surface area catches more air', hint: 'A bigger surface pushes against more air' },
    ],
  },

